<script setup>
import { onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import http from '../../api/http'
const route=useRoute(); const categories=ref([]); const papers=ref([]); const category=ref(null); const loading=ref(true); const error=ref('')
onMounted(async()=>{try{if(route.params.slug){const {data}=await http.get(`/gk/exam-categories/${encodeURIComponent(route.params.slug)}`);category.value=data.category;papers.value=data.data||[]}else{const {data}=await http.get('/gk/exam-categories');categories.value=data.data||[]}}catch(e){error.value=e.response?.data?.message||'পরীক্ষার তালিকা আনা যায়নি।'}finally{loading.value=false}})
watch(()=>route.params.slug,()=>window.location.reload())</script>
<template><main class="container-page py-10"><header class="mb-7 rounded-3xl bg-emerald-950 p-7 text-white"><p class="text-sm text-emerald-200">সহজপাঠ · MCQ পরীক্ষা</p><h1 class="mt-2 text-3xl font-black">{{ category?.name || 'পরীক্ষার বিভাগ' }}</h1><p class="mt-2 text-sm text-emerald-100">বিভাগ বেছে নিয়ে প্রকাশিত পরীক্ষায় অংশ নিন।</p></header><p v-if="loading" class="surface p-10 text-center">লোড হচ্ছে…</p><p v-else-if="error" class="surface p-8 text-center text-rose-700">{{ error }}</p><div v-else-if="category" class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><article v-for="paper in papers" :key="paper.id" class="surface p-5"><span class="pill">{{ paper.question_count }} প্রশ্ন · {{ paper.duration_minutes }} মিনিট</span><h2 class="mt-3 text-lg font-extrabold">{{ paper.title }}</h2><div class="mt-4 flex flex-wrap gap-2"><RouterLink class="rounded-xl border border-emerald-700 px-4 py-3 text-sm font-bold text-emerald-800 transition hover:bg-emerald-50" :to="'/gk/exam-paper/'+paper.id+'/preview'">Preview</RouterLink><RouterLink class="btn-primary" :to="'/gk/exam-paper/'+paper.id">পরীক্ষা শুরু করুন →</RouterLink></div></article><p v-if="!papers.length" class="surface p-8 text-center text-slate-500">এই বিভাগে এখনো কোনো প্রকাশিত পরীক্ষা নেই।</p></div><div v-else class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><RouterLink v-for="item in categories" :key="item.id" :to="`/gk/exam-categories/${item.slug}`" class="surface p-6 transition hover:-translate-y-1 hover:shadow-lg"><span class="text-3xl">📚</span><h2 class="mt-3 text-xl font-extrabold">{{ item.name }}</h2><p class="mt-1 text-sm text-slate-500">{{ item.paper_count }}টি প্রকাশিত পরীক্ষা</p><span class="mt-4 inline-flex font-bold text-emerald-700">পরীক্ষা দেখুন →</span></RouterLink><p v-if="!categories.length" class="surface p-8 text-center text-slate-500">এখনো কোনো পরীক্ষার বিভাগ প্রকাশিত হয়নি।</p></div></main></template>